class Solution:
    def intersect(self, nums1: list[int], nums2: list[int]) -> list[int]:
        from collections import Counter
        counts = Counter(nums1)
        result = []
        for n in nums2:
            if counts[n] > 0:
                result.append(n)
                counts[n] -= 1
        return result

